// In C++98/03, these are the basic rules.

// Rule: If no constructors are declared, compiler generates a default ctor.
class AllGenerated {
    // Compiler generates default ctor, dtor, copy ctor, copy assignment.
};

// Rule: Declaring any constructor prevents default ctor generation.
class NoDefaultCtor {
public:
    // User-declared constructor suppresses compiler's default ctor.
    explicit NoDefaultCtor(int) {}
    // Compiler still generates dtor, copy ctor, copy assignment.
};

void test() {
    AllGenerated ag1;          // OK: Uses generated default ctor
    AllGenerated ag2 = ag1;    // OK: Uses generated copy ctor

    // NoDefaultCtor ndc1;     // COMPILE ERROR! No default constructor exists.
    NoDefaultCtor ndc2(42);  // OK: Uses user-declared constructor.
}
